let originalFile=null,originalUrl='',sourceImg=null,cutoutBlob=null,cutoutUrl='',bgMode='transparent',bgColor='#ffffff',bgImage=null,soft=0,shadow=0,bgBlur=0,ratio=1,format='png',history=[],future=[];
