function wait(ms){return new Promise(r=>setTimeout(r,ms))}
function activeButton(selector,el){document.querySelectorAll(selector).forEach(x=>x.classList.remove('active'));el.classList.add('active')}
function drawCover(image,x,y,w,h,blur=0){ctx.save();if(blur)ctx.filter=`blur(${blur}px)`;const ir=image.width/image.height,cr=w/h;let dw=w,dh=h;if(ir>cr){dh=h;dw=h*ir}else{dw=w;dh=w/ir}ctx.drawImage(image,x+(w-dw)/2,y+(h-dh)/2,dw,dh);ctx.restore()}
function render(){if(!sourceImg)return;const iw=sourceImg.naturalWidth||sourceImg.width,ih=sourceImg.naturalHeight||sourceImg.height;let cw=iw,ch=ih;if(ratio){if(iw/ih>ratio)ch=Math.round(iw/ratio);else cw=Math.round(ih*ratio)}const max=1800,scale=Math.min(1,max/Math.max(cw,ch));cw=Math.max(1,Math.round(cw*scale));ch=Math.max(1,Math.round(ch*scale));canvas.width=cw;canvas.height=ch;ctx.clearRect(0,0,cw,ch);if(bgMode==='transparent'){}else if(bgImage){drawCover(bgImage,0,0,cw,ch,bgBlur)}else{ctx.fillStyle=bgColor;ctx.fillRect(0,0,cw,ch)}const img=cutoutBlob?sourceImg:null;if(img){const cu=cutoutUrl;const ci=new Image();ci.onload=()=>drawSubject(ci,cw,ch);ci.src=cu}else{drawSubject(sourceImg,cw,ch)}}
function drawSubject(ci,cw,ch){ctx.save();if(shadow){ctx.shadowColor='rgba(0,0,0,.28)';ctx.shadowBlur=shadow*1.3;ctx.shadowOffsetY=shadow*.35}const ir=ci.width/ci.height,cr=cw/ch;let dw=cw,dh=ch;if(ir>cr){dh=cw/ir}else{dw=ch*ir}const x=(cw-dw)/2,y=(ch-dh)/2;ctx.globalAlpha=1;ctx.filter=soft?`blur(${soft/2}px)`:'none';ctx.drawImage(ci,x,y,dw,dh);ctx.restore();updatePreview()}
function updatePreview(){const url=canvas.toDataURL('image/png');resultImg.src=url;afterImg.src=url;download2.href=url;download2.download='smarttoolz-image.'+(format==='jpeg'?'jpg':format);resultImg.dataset.url=url;$('resultMeta').textContent=`${canvas.width} × ${canvas.height} • ${format.toUpperCase()}`;download.disabled=false}
function setResult(){updatePreview();results.scrollIntoView({behavior:'smooth',block:'start'})}
$('removeBtn').onclick=()=>{if(!originalFile)return;pushHistory();cutoutBlob=cutoutBlob||null;bgMode='transparent';bgImage=null;render();status('Transparent background selected')};
$('restoreBtn').onclick=()=>{if(!originalFile)return;pushHistory();cutoutBlob=null;if(cutoutUrl){URL.revokeObjectURL(cutoutUrl);cutoutUrl=''};bgMode='transparent';render();status('Original image restored');toast('Original background restored')};
document.querySelectorAll('.bgBtn').forEach(b=>b.onclick=()=>{if(!sourceImg)return;pushHistory();bgMode=b.dataset.bg;if(bgMode==='white')bgColor='#fff';if(bgMode==='black')bgColor='#111827';bgImage=null;activeButton('.bgBtn',b);render()});
document.querySelectorAll('.sw').forEach(b=>b.onclick=()=>{if(!sourceImg)return;pushHistory();bgMode='color';bgColor=b.dataset.color;$('color').value=bgColor;bgImage=null;document.querySelectorAll('.bgBtn').forEach(x=>x.classList.remove('active'));render()});
$('color').oninput=e=>{if(!sourceImg)return;bgColor=e.target.value;bgMode='color';bgImage=null;document.querySelectorAll('.bgBtn').forEach(x=>x.classList.remove('active'));render()};
$('bgPicker').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;pushHistory();bgImage=await loadImage(f);bgMode='image';document.querySelectorAll('.bgBtn').forEach(x=>x.classList.remove('active'));render();toast('Background added')};
$('soft').oninput=e=>{soft=+e.target.value;$('softVal').textContent=soft;render()};$('shadow').oninput=e=>{shadow=+e.target.value;$('shadowVal').textContent=shadow;render()};$('bgBlur').oninput=e=>{bgBlur=+e.target.value;$('bgBlurVal').textContent=bgBlur;render()};
document.querySelectorAll('.ratio').forEach(b=>b.onclick=()=>{if(!sourceImg)return;pushHistory();ratio=+b.dataset.ratio;activeButton('.ratio',b);render()});document.querySelectorAll('.format').forEach(b=>b.onclick=()=>{format=b.dataset.format;activeButton('.format',b);updatePreview()});
document.querySelectorAll('.tab').forEach(tab=>tab.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));tab.classList.add('active');document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));const p=document.querySelector(`[data-panel="${tab.dataset.tab}"]`);if(p)p.classList.add('active')});
picker.onchange=e=>{const f=e.target.files?.[0];picker.value='';chooseFile(f)};
const dropZone=$('dropZone');['dragenter','dragover'].forEach(ev=>dropZone.addEventListener(ev,e=>{e.preventDefault();empty?.classList.add('dragging')}));['dragleave','drop'].forEach(ev=>dropZone.addEventListener(ev,e=>{e.preventDefault();empty?.classList.remove('dragging')}));dropZone.addEventListener('drop',e=>{const f=e.dataTransfer.files?.[0];if(f)chooseFile(f)});
document.addEventListener('paste',e=>{const item=[...(e.clipboardData?.items||[])].find(i=>i.type.startsWith('image/'));if(item)chooseFile(item.getAsFile())});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='o'){e.preventDefault();picker.click()}if(e.key==='Escape'&&processing.style.display==='block'){e.preventDefault()}});
$('download').onclick=()=>exportImage();$('download2').onclick=()=>{setTimeout(()=>toast('Export ready'),50)};$('editAgain').onclick=()=>document.querySelector('.studio').scrollIntoView({behavior:'smooth'});
function exportImage(){if(!sourceImg)return;const mime=format==='jpeg'?'image/jpeg':format==='webp'?'image/webp':'image/png';const url=canvas.toDataURL(mime,format==='png'?1:.92);const a=document.createElement('a');a.href=url;a.download='smarttoolz-image.'+(format==='jpeg'?'jpg':format);a.click();toast('Image exported')}
$('reset').onclick=()=>{if(!sourceImg)return;pushHistory();bgMode='transparent';bgColor='#fff';bgImage=null;soft=0;shadow=0;bgBlur=0;ratio=1;format='png';$('color').value=bgColor;$('soft').value=0;$('shadow').value=0;$('bgBlur').value=0;$('softVal').textContent='0';$('shadowVal').textContent='0';$('bgBlurVal').textContent='0';document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));document.querySelector('.ratio[data-ratio="1"]').classList.add('active');document.querySelector('.format[data-format="png"]').classList.add('active');document.querySelector('.bgBtn[data-bg="transparent"]').classList.add('active');render();toast('Canvas reset')};
$('newImage').onclick=()=>picker.click();$('undo').onclick=()=>{if(!history.length)return;future.push({bgMode,bgColor,bgImage,soft,shadow,bgBlur,ratio,format});restoreState(history.pop());toast('Undo')};$('redo').onclick=()=>{if(!future.length)return;history.push({bgMode,bgColor,bgImage,soft,shadow,bgBlur,ratio,format});restoreState(future.pop());toast('Redo')};$('compare').oninput=e=>{$('afterImg').parentElement.style.width=e.target.value+'%';$('compareLine').style.left=e.target.value+'%'};
window.addEventListener('beforeunload',()=>{if(originalUrl)URL.revokeObjectURL(originalUrl);if(cutoutUrl)URL.revokeObjectURL(cutoutUrl)});
</script>
</body></html>
